head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > minYear]<br/>Calendar 컴포넌트에서 선택할 수 있는 최소 연도를 설정합니다.",
    "validation" : [
        "Number 값으로 연도 범위의 하한값을 4자리 양의 정수로 설정합니다.",
        "값을 설정하지 않으면 config.xml 의 /WebSquare/calendar/minYear/@value 설정값이 적용되며, 기본 배포 값은 '1978' 입니다.",
        "연도 SelectBox 에 minYear 속성값부터 maxYear 속성값까지의 연도가 표시됩니다.",
        "minYear 속성값의 1월에서 이전 달/이전 연도 이동이 차단됩니다.",
        "gotoCalendar() 메소드로 minYear 미만의 연도를 설정하면 minYear 로 적용됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        minYear : con_minYear.getValue(),
        maxYear : con_maxYear.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);

    // minYear 의 1월로 초기 이동 (이전월 이동 차단 검증 편의)
    let minY = parseInt(target1.options.minYear);
    if (!isNaN(minY)) {
        target1.gotoCalendar(minY + "0101");
    }
}



// validation: gotoCalendar() 메소드로 minYear 미만의 연도를 설정하면 minYear 로 적용됨
scwin.btn_gotoUnderMinYear_onclick = function (e) {
    let minY = parseInt(target1.options.minYear);
    if (isNaN(minY)) {
        wf_body_bottom.getObj("scwin").setReturnValue("[gotoCalendar 미만 시도] minYear 가 숫자가 아님");
        return;
    }

    // minYear - 75년의 임의 미만값 (음수가 되지 않도록 보장)
    let underYear = Math.max(1, (minY - 75));
    // 4자리 패딩
    let underYearStr = ("0000" + underYear).slice(-4);
    let dateStr = underYearStr + "0101";
    target1.gotoCalendar(dateStr);

    let returnValue = target1.getValue();
    let returnedYear = returnValue.substring(0, 4);
    let clamped = (parseInt(returnedYear) === minY);

    wf_body_bottom.getObj("scwin").setReturnValue("[gotoCalendar 미만 시도 결과] 요청='" + dateStr + "', getValue()='" + returnValue + "', 반환된 연도=" + returnedYear + " (minYear=" + minY + ") → " + (clamped ? "minYear 로 클램핑됨" : "클램핑되지 않음"));
};
